package com.jobpilot.integration;import com.jobpilot.user.User;import jakarta.persistence.*;import java.time.LocalDateTime;@Entity @Table(name="search_preferences")public class SearchPreference{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@OneToOne(optional=false)@JoinColumn(name="user_id",unique=true)private User user;@Column(nullable=false)private String keywords="Angular";@Column(nullable=false)private String country="co";private String location="Colombia";private boolean remoteOnly=true;private LocalDateTime lastSyncAt;public Long getId(){return id;}public User getUser(){return user;}public void setUser(User v){user=v;}public String getKeywords(){return keywords;}public void setKeywords(String v){keywords=v;}public String getCountry(){return country;}public void setCountry(String v){country=v;}public String getLocation(){return location;}public void setLocation(String v){location=v;}public boolean isRemoteOnly(){return remoteOnly;}public void setRemoteOnly(boolean v){remoteOnly=v;}public LocalDateTime getLastSyncAt(){return lastSyncAt;}public void setLastSyncAt(LocalDateTime v){lastSyncAt=v;}}
